import{i as e,r as t,s as n,t as r}from"./app-C69iBeF_.js";var i=JSON.parse(`{"path":"/posts/tech/raw-proce.html","title":"OpenCameraIQ：面向 RAW/ISP 的结构与噪声感知图像恢复平台","lang":"zh-CN","frontmatter":{"icon":"pen-to-square","date":"2026-03-03T00:00:00.000Z","category":"-计算摄影","tag":"-RAW -ISP","description":"OpenCameraIQ：面向 RAW/ISP 的结构与噪声感知图像恢复平台 整体流程可以概括为： 项目工程主干采用 C++17，围绕 Camera Source → Frame → ISP Pipeline → Metrics 进行模块化设计，并通过 Web 调参台观察处理结果、图像统计和运行性能。 在此基础上，我选择了两个比较典型的 RAW 图像问...","head":[["script",{"type":"application/ld+json"},"{\\"@context\\":\\"https://schema.org\\",\\"@type\\":\\"Article\\",\\"headline\\":\\"OpenCameraIQ：面向 RAW/ISP 的结构与噪声感知图像恢复平台\\",\\"image\\":[\\"\\"],\\"datePublished\\":\\"2026-03-03T00:00:00.000Z\\",\\"dateModified\\":null,\\"author\\":[{\\"@type\\":\\"Person\\",\\"name\\":\\"Sinthome\\",\\"url\\":\\"https://github.com/LSGE271828\\"}]}"],["meta",{"property":"og:url","content":"https://LSGE271828.github.io/posts/tech/raw-proce.html"}],["meta",{"property":"og:site_name","content":"Sinthome"}],["meta",{"property":"og:title","content":"OpenCameraIQ：面向 RAW/ISP 的结构与噪声感知图像恢复平台"}],["meta",{"property":"og:description","content":"OpenCameraIQ：面向 RAW/ISP 的结构与噪声感知图像恢复平台 整体流程可以概括为： 项目工程主干采用 C++17，围绕 Camera Source → Frame → ISP Pipeline → Metrics 进行模块化设计，并通过 Web 调参台观察处理结果、图像统计和运行性能。 在此基础上，我选择了两个比较典型的 RAW 图像问..."}],["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:locale","content":"zh-CN"}],["meta",{"property":"article:tag","content":"-RAW -ISP"}],["meta",{"property":"article:published_time","content":"2026-03-03T00:00:00.000Z"}]]},"git":{},"readingTime":{"minutes":9.13,"words":2739},"filePathRelative":"posts/tech/raw-proce.md","excerpt":"\\n<pre><code>OpenCameraIQ 是一个围绕 **Camera RAW、ISP Pipeline 与图像质量分析**搭建的实验平台。\\n\\n项目关注的并不是单独实现某一个图像处理算法，而是希望把 RAW 输入、Metadata 解析、图像恢复、ISP 处理、质量评价以及可视化调试串成一条完整链路。\\n</code></pre>\\n<p>整体流程可以概括为：</p>\\n<div class=\\"language-text line-numbers-mode\\" data-highlighter=\\"shiki\\" data-ext=\\"text\\" style=\\"--shiki-light:#383A42;--shiki-dark:#abb2bf;--shiki-light-bg:#FAFAFA;--shiki-dark-bg:#282c34\\"><pre class=\\"shiki shiki-themes one-light one-dark-pro vp-code\\"><code class=\\"language-text\\"><span class=\\"line\\"><span>RAW / Camera Frame</span></span>\\n<span class=\\"line\\"><span>        ↓</span></span>\\n<span class=\\"line\\"><span>Camera Source</span></span>\\n<span class=\\"line\\"><span>        ↓</span></span>\\n<span class=\\"line\\"><span>RAW Metadata / Normalize</span></span>\\n<span class=\\"line\\"><span>        ↓</span></span>\\n<span class=\\"line\\"><span>ISP / Image Restoration</span></span>\\n<span class=\\"line\\"><span>        ↓</span></span>\\n<span class=\\"line\\"><span>Image Quality Metrics</span></span>\\n<span class=\\"line\\"><span>        ↓</span></span>\\n<span class=\\"line\\"><span>Web Tuning Console</span></span></code></pre>\\n<div class=\\"line-numbers\\" aria-hidden=\\"true\\" style=\\"counter-reset:line-number 0\\"><div class=\\"line-number\\"></div><div class=\\"line-number\\"></div><div class=\\"line-number\\"></div><div class=\\"line-number\\"></div><div class=\\"line-number\\"></div><div class=\\"line-number\\"></div><div class=\\"line-number\\"></div><div class=\\"line-number\\"></div><div class=\\"line-number\\"></div><div class=\\"line-number\\"></div><div class=\\"line-number\\"></div></div></div>","autoDesc":true}`),a={name:`raw-proce.md`};function o(r,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[e(`<h1 id="opencameraiq-面向-raw-isp-的结构与噪声感知图像恢复平台" tabindex="-1"><a class="header-anchor" href="#opencameraiq-面向-raw-isp-的结构与噪声感知图像恢复平台"><span>OpenCameraIQ：面向 RAW/ISP 的结构与噪声感知图像恢复平台</span></a></h1><pre><code>OpenCameraIQ 是一个围绕 **Camera RAW、ISP Pipeline 与图像质量分析**搭建的实验平台。

项目关注的并不是单独实现某一个图像处理算法，而是希望把 RAW 输入、Metadata 解析、图像恢复、ISP 处理、质量评价以及可视化调试串成一条完整链路。
</code></pre><p>整体流程可以概括为：</p><div class="language-text line-numbers-mode" data-highlighter="shiki" data-ext="text" style="--shiki-light:#383A42;--shiki-dark:#abb2bf;--shiki-light-bg:#FAFAFA;--shiki-dark-bg:#282c34;"><pre class="shiki shiki-themes one-light one-dark-pro vp-code"><code class="language-text"><span class="line"><span>RAW / Camera Frame</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>Camera Source</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>RAW Metadata / Normalize</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>ISP / Image Restoration</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>Image Quality Metrics</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>Web Tuning Console</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>项目工程主干采用 C++17，围绕 <code>Camera Source → Frame → ISP Pipeline → Metrics</code> 进行模块化设计，并通过 Web 调参台观察处理结果、图像统计和运行性能。</p><p>在此基础上，我选择了两个比较典型的 RAW 图像问题进行实验：</p><ul><li><strong>Quad-Bayer 特殊 CFA 结构恢复</strong></li><li><strong>真实手机 RAW 噪声恢复</strong></li></ul><p>二者分别对应 RAW Pipeline 中两个不同的问题：</p><div class="language-text line-numbers-mode" data-highlighter="shiki" data-ext="text" style="--shiki-light:#383A42;--shiki-dark:#abb2bf;--shiki-light-bg:#FAFAFA;--shiki-dark-bg:#282c34;"><pre class="shiki shiki-themes one-light one-dark-pro vp-code"><code class="language-text"><span class="line"><span>采样结构变化</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>Pattern-Aware Reconstruction</span></span>
<span class="line"><span></span></span>
<span class="line"><span>真实传感器噪声</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>Noise-Aware Restoration</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>最终统一输出为标准 Bayer RAW，再进入后续 ISP。</p><hr><h2 id="一、为什么从-raw-域开始处理" tabindex="-1"><a class="header-anchor" href="#一、为什么从-raw-域开始处理"><span>一、为什么从 RAW 域开始处理</span></a></h2><p>常见图像算法通常直接处理 RGB 或 JPEG 图像，但对于 Camera / ISP 来说，很多问题在转换到 RGB 之前就已经发生。</p><p>Sensor 输出的 RAW 数据中仍然保留：</p><div class="language-text line-numbers-mode" data-highlighter="shiki" data-ext="text" style="--shiki-light:#383A42;--shiki-dark:#abb2bf;--shiki-light-bg:#FAFAFA;--shiki-dark-bg:#282c34;"><pre class="shiki shiki-themes one-light one-dark-pro vp-code"><code class="language-text"><span class="line"><span>Bayer Pattern</span></span>
<span class="line"><span>Black Level</span></span>
<span class="line"><span>White Level</span></span>
<span class="line"><span>ISO</span></span>
<span class="line"><span>Exposure</span></span>
<span class="line"><span>White Balance Metadata</span></span>
<span class="line"><span>Color Matrix</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>这些信息直接决定后续 ISP 如何解释像素。</p><p>例如，同样一个像素值，在不同 ISO、曝光时间、Black Level 或 CFA Pattern 下，实际物理意义并不相同。</p><p>因此，在 RAW 域进行图像恢复时，不能简单把输入看成普通灰度图，而需要同时考虑：</p><ul><li>Sensor 采样方式；</li><li>CFA Pattern；</li><li>信号动态范围；</li><li>Sensor Noise；</li><li>Camera Metadata；</li><li>后续 ISP Pipeline。</li></ul><p>项目中已经实现 RAW/DNG Metadata 检查工具，可以读取 Bayer Pattern、Black Level、White Level、ISO、曝光以及白平衡等关键参数。</p><hr><h1 id="二、quad-bayer-特殊-cfa-结构恢复" tabindex="-1"><a class="header-anchor" href="#二、quad-bayer-特殊-cfa-结构恢复"><span>二、Quad-Bayer：特殊 CFA 结构恢复</span></a></h1><p>Quad-Bayer 是手机 Camera 中比较典型的一类 CFA。</p><p>传统 Bayer 一般采用类似 RGGB 的 (2\\times2) 周期结构，而 Quad-Bayer 会让多个相邻像素具有相同颜色。</p><p>这种设计可以在低照条件下通过 Pixel Binning 提高感光能力，但同时也带来一个问题：</p><blockquote><p>原始 Quad-Bayer RAW 不能直接按照标准 Bayer RAW 进入普通 ISP Pipeline。</p></blockquote><p>因此需要进行 <strong>Remosaic</strong>。</p><h3 id="_1-quad-cfa-采样模型" tabindex="-1"><a class="header-anchor" href="#_1-quad-cfa-采样模型"><span>1. Quad CFA 采样模型</span></a></h3><p>可以将 Quad-Bayer RAW 表示为：</p><p class="katex-block"><span class="katex-display"><span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML" display="block"><semantics><mrow><mi>Q</mi><mo stretchy="false">(</mo><mi>x</mi><mo separator="true">,</mo><mi>y</mi><mo stretchy="false">)</mo><mo>=</mo><msub><mi>M</mi><mi>Q</mi></msub><mo stretchy="false">(</mo><mi>x</mi><mo separator="true">,</mo><mi>y</mi><mo stretchy="false">)</mo><mo>⊙</mo><mi>I</mi><mo stretchy="false">(</mo><mi>x</mi><mo separator="true">,</mo><mi>y</mi><mo stretchy="false">)</mo></mrow><annotation encoding="application/x-tex">Q(x,y)=M_Q(x,y)\\odot I(x,y) </annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord mathnormal">Q</span><span class="mopen">(</span><span class="mord mathnormal">x</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal" style="margin-right:0.0359em;">y</span><span class="mclose">)</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1.0361em;vertical-align:-0.2861em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.109em;">M</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3283em;"><span style="top:-2.55em;margin-left:-0.109em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">Q</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2861em;"><span></span></span></span></span></span></span><span class="mopen">(</span><span class="mord mathnormal">x</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal" style="margin-right:0.0359em;">y</span><span class="mclose">)</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">⊙</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord mathnormal" style="margin-right:0.0785em;">I</span><span class="mopen">(</span><span class="mord mathnormal">x</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal" style="margin-right:0.0359em;">y</span><span class="mclose">)</span></span></span></span></span></p><p>其中：</p><ul><li>(I(x,y))：理想连续图像；</li><li>(M_Q(x,y))：Quad CFA Sampling Mask；</li><li>(Q(x,y))：Sensor 实际采样得到的 RAW。</li></ul><p>这里的核心问题并不是简单插值，而是：</p><blockquote><p>如何根据 CFA Pattern 和局部结构，将 Quad-Bayer 重新映射为标准 Bayer Pattern。</p></blockquote><hr><h2 id="三、pattern-aware-remosaic" tabindex="-1"><a class="header-anchor" href="#三、pattern-aware-remosaic"><span>三、Pattern-Aware Remosaic</span></a></h2><p>对于待恢复像素 (p)，可以从相同 Color Plane 的邻域中估计：</p><p class="katex-block"><span class="katex-display"><span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML" display="block"><semantics><mrow><msub><mover accent="true"><mi>B</mi><mo>^</mo></mover><mi>R</mi></msub><mo stretchy="false">(</mo><mi>p</mi><mo stretchy="false">)</mo><mo>=</mo><mfrac><mrow><munder><mo>∑</mo><mrow><mi>q</mi><mo>∈</mo><msub><mi>N</mi><mi>R</mi></msub><mo stretchy="false">(</mo><mi>p</mi><mo stretchy="false">)</mo></mrow></munder><mi>w</mi><mo stretchy="false">(</mo><mi>p</mi><mo separator="true">,</mo><mi>q</mi><mo stretchy="false">)</mo><mi>Q</mi><mo stretchy="false">(</mo><mi>q</mi><mo stretchy="false">)</mo></mrow><mrow><munder><mo>∑</mo><mrow><mi>q</mi><mo>∈</mo><msub><mi>N</mi><mi>R</mi></msub><mo stretchy="false">(</mo><mi>p</mi><mo stretchy="false">)</mo></mrow></munder><mi>w</mi><mo stretchy="false">(</mo><mi>p</mi><mo separator="true">,</mo><mi>q</mi><mo stretchy="false">)</mo></mrow></mfrac></mrow><annotation encoding="application/x-tex">\\hat B_R(p)= \\frac{ \\sum_{q\\in N_R(p)} w(p,q)Q(q) }{ \\sum_{q\\in N_R(p)} w(p,q) } </annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1.1968em;vertical-align:-0.25em;"></span><span class="mord"><span class="mord accent"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.9468em;"><span style="top:-3em;"><span class="pstrut" style="height:3em;"></span><span class="mord mathnormal" style="margin-right:0.0502em;">B</span></span><span style="top:-3.2523em;"><span class="pstrut" style="height:3em;"></span><span class="accent-body" style="left:-0.1667em;"><span class="mord">^</span></span></span></span></span></span></span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3283em;"><span style="top:-2.55em;margin-left:-0.0502em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight" style="margin-right:0.0077em;">R</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mopen">(</span><span class="mord mathnormal">p</span><span class="mclose">)</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:2.7754em;vertical-align:-1.1607em;"></span><span class="mord"><span class="mopen nulldelimiter"></span><span class="mfrac"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:1.6147em;"><span style="top:-2.314em;"><span class="pstrut" style="height:3em;"></span><span class="mord"><span class="mop"><span class="mop op-symbol small-op" style="position:relative;top:0em;">∑</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.2253em;"><span style="top:-2.4003em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight" style="margin-right:0.0359em;">q</span><span class="mrel mtight">∈</span><span class="mord mtight"><span class="mord mathnormal mtight" style="margin-right:0.109em;">N</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3448em;"><span style="top:-2.3567em;margin-left:-0.109em;margin-right:0.0714em;"><span class="pstrut" style="height:2.5em;"></span><span class="sizing reset-size3 size1 mtight"><span class="mord mathnormal mtight" style="margin-right:0.0077em;">R</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.1433em;"><span></span></span></span></span></span></span><span class="mopen mtight">(</span><span class="mord mathnormal mtight">p</span><span class="mclose mtight">)</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.4747em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal" style="margin-right:0.0269em;">w</span><span class="mopen">(</span><span class="mord mathnormal">p</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal" style="margin-right:0.0359em;">q</span><span class="mclose">)</span></span></span><span style="top:-3.23em;"><span class="pstrut" style="height:3em;"></span><span class="frac-line" style="border-bottom-width:0.04em;"></span></span><span style="top:-3.8647em;"><span class="pstrut" style="height:3em;"></span><span class="mord"><span class="mop"><span class="mop op-symbol small-op" style="position:relative;top:0em;">∑</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.2253em;"><span style="top:-2.4003em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight" style="margin-right:0.0359em;">q</span><span class="mrel mtight">∈</span><span class="mord mtight"><span class="mord mathnormal mtight" style="margin-right:0.109em;">N</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3448em;"><span style="top:-2.3567em;margin-left:-0.109em;margin-right:0.0714em;"><span class="pstrut" style="height:2.5em;"></span><span class="sizing reset-size3 size1 mtight"><span class="mord mathnormal mtight" style="margin-right:0.0077em;">R</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.1433em;"><span></span></span></span></span></span></span><span class="mopen mtight">(</span><span class="mord mathnormal mtight">p</span><span class="mclose mtight">)</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.4747em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal" style="margin-right:0.0269em;">w</span><span class="mopen">(</span><span class="mord mathnormal">p</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal" style="margin-right:0.0359em;">q</span><span class="mclose">)</span><span class="mord mathnormal">Q</span><span class="mopen">(</span><span class="mord mathnormal" style="margin-right:0.0359em;">q</span><span class="mclose">)</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:1.1607em;"><span></span></span></span></span></span><span class="mclose nulldelimiter"></span></span></span></span></span></span></p><p>其中：</p><ul><li>(N_R(p)) 表示当前位置附近相同颜色的有效采样点；</li><li>(w(p,q)) 表示根据空间距离和局部结构计算得到的权重。</li></ul><p>如果只进行简单均值插值，在文字、棋盘格、树叶等高频区域很容易产生：</p><div class="language-text line-numbers-mode" data-highlighter="shiki" data-ext="text" style="--shiki-light:#383A42;--shiki-dark:#abb2bf;--shiki-light-bg:#FAFAFA;--shiki-dark-bg:#282c34;"><pre class="shiki shiki-themes one-light one-dark-pro vp-code"><code class="language-text"><span class="line"><span>False Color</span></span>
<span class="line"><span>Zipper Artifact</span></span>
<span class="line"><span>Edge Blur</span></span>
<span class="line"><span>Texture Loss</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>因此恢复过程中需要显式感知局部结构。</p><p>完整处理路径为：</p><div class="language-text line-numbers-mode" data-highlighter="shiki" data-ext="text" style="--shiki-light:#383A42;--shiki-dark:#abb2bf;--shiki-light-bg:#FAFAFA;--shiki-dark-bg:#282c34;"><pre class="shiki shiki-themes one-light one-dark-pro vp-code"><code class="language-text"><span class="line"><span>Quad-Bayer RAW</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>CFA Pattern Identification</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>Pattern-Aware Remosaic</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>Joint Denoise</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>Standard Bayer RAW</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>当前平台已经能够对 Quad-Bayer 内置样例运行完整实验，并输出 RAW Preview、最终重建结果以及局部细节、ColorChecker 等对比结果。</p><hr><h1 id="四、真实-raw-噪声不是简单高斯噪声" tabindex="-1"><a class="header-anchor" href="#四、真实-raw-噪声不是简单高斯噪声"><span>四、真实 RAW 噪声不是简单高斯噪声</span></a></h1><p>第二个实验关注真实手机 Camera 的 RAW Noise。</p><p>很多基础图像处理实验会直接加入固定方差的 Gaussian Noise：</p><p class="katex-block"><span class="katex-display"><span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML" display="block"><semantics><mrow><mi>y</mi><mo>=</mo><mi>x</mi><mo>+</mo><mi>n</mi></mrow><annotation encoding="application/x-tex">y=x+n </annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.625em;vertical-align:-0.1944em;"></span><span class="mord mathnormal" style="margin-right:0.0359em;">y</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6667em;vertical-align:-0.0833em;"></span><span class="mord mathnormal">x</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">+</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.4306em;"></span><span class="mord mathnormal">n</span></span></span></span></span></p><p>但真实 Sensor Noise 通常具有明显的 <strong>Signal-Dependent</strong> 特征。</p><p>一个常用近似模型为：</p><p class="katex-block"><span class="katex-display"><span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML" display="block"><semantics><mrow><msubsup><mi>σ</mi><mi>i</mi><mn>2</mn></msubsup><mo>≈</mo><mi>a</mi><msub><mi>y</mi><mi>i</mi></msub><mo>+</mo><mi>b</mi></mrow><annotation encoding="application/x-tex">\\sigma_i^2 \\approx ay_i+b </annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1.1111em;vertical-align:-0.247em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0359em;">σ</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.8641em;"><span style="top:-2.453em;margin-left:-0.0359em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">i</span></span></span><span style="top:-3.113em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">2</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.247em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">≈</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.7778em;vertical-align:-0.1944em;"></span><span class="mord mathnormal">a</span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0359em;">y</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3117em;"><span style="top:-2.55em;margin-left:-0.0359em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">i</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">+</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.6944em;"></span><span class="mord mathnormal">b</span></span></span></span></span></p><p>其中：</p><ul><li>(ay_i)：主要对应与信号强度相关的 Shot Noise；</li><li>(b)：主要对应 Read Noise 等信号无关噪声。</li></ul><p>因此：</p><blockquote><p>RAW 图像不同位置的 Noise Level 本身就可能不同。</p></blockquote><p>亮区、暗区不能简单使用完全相同的去噪强度。</p><hr><h1 id="五、noise-aware-raw-restoration" tabindex="-1"><a class="header-anchor" href="#五、noise-aware-raw-restoration"><span>五、Noise-Aware RAW Restoration</span></a></h1><p>为了利用噪声统计特性，可以将恢复过程写成：</p><p class="katex-block"><span class="katex-display"><span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML" display="block"><semantics><mrow><mover accent="true"><mi>x</mi><mo>^</mo></mover><mo>=</mo><mo>=</mo><mo>=</mo><mo>=</mo><mo>=</mo><mo>=</mo><mo>=</mo><mi>arg</mi><mo>⁡</mo><munder><mrow><mi>min</mi><mo>⁡</mo></mrow><mi>x</mi></munder><mfrac><mn>1</mn><mn>2</mn></mfrac><munder><mo>∑</mo><mi>i</mi></munder><mfrac><mrow><mo stretchy="false">(</mo><msub><mi>x</mi><mi>i</mi></msub><mo>−</mo><msub><mi>y</mi><mi>i</mi></msub><msup><mo stretchy="false">)</mo><mn>2</mn></msup></mrow><mrow><mi>a</mi><msub><mi>y</mi><mi>i</mi></msub><mo>+</mo><mi>b</mi><mo>+</mo><mi>ε</mi></mrow></mfrac><mo>+</mo><mi>λ</mi><munder><mo>∑</mo><mi>i</mi></munder><msub><mi>ρ</mi><mi>δ</mi></msub><mo stretchy="false">(</mo><mi mathvariant="normal">∣</mi><mi mathvariant="normal">∇</mi><msub><mi>x</mi><mi>i</mi></msub><mi mathvariant="normal">∣</mi><mo stretchy="false">)</mo></mrow><annotation encoding="application/x-tex">\\hat{x} ======= \\arg\\min_x \\frac{1}{2} \\sum_i \\frac{(x_i-y_i)^2} {ay_i+b+\\varepsilon} + \\lambda \\sum_i \\rho_\\delta(|\\nabla x_i|) </annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6944em;"></span><span class="mord accent"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.6944em;"><span style="top:-3em;"><span class="pstrut" style="height:3em;"></span><span class="mord mathnormal">x</span></span><span style="top:-3em;"><span class="pstrut" style="height:3em;"></span><span class="accent-body" style="left:-0.2222em;"><span class="mord">^</span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=======</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:2.7688em;vertical-align:-1.2777em;"></span><span class="mop">ar<span style="margin-right:0.0139em;">g</span></span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mop op-limits"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.6679em;"><span style="top:-2.4em;margin-left:0em;"><span class="pstrut" style="height:3em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">x</span></span></span><span style="top:-3em;"><span class="pstrut" style="height:3em;"></span><span><span class="mop">min</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.7em;"><span></span></span></span></span></span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mopen nulldelimiter"></span><span class="mfrac"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:1.3214em;"><span style="top:-2.314em;"><span class="pstrut" style="height:3em;"></span><span class="mord"><span class="mord">2</span></span></span><span style="top:-3.23em;"><span class="pstrut" style="height:3em;"></span><span class="frac-line" style="border-bottom-width:0.04em;"></span></span><span style="top:-3.677em;"><span class="pstrut" style="height:3em;"></span><span class="mord"><span class="mord">1</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.686em;"><span></span></span></span></span></span><span class="mclose nulldelimiter"></span></span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mop op-limits"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:1.05em;"><span style="top:-1.8723em;margin-left:0em;"><span class="pstrut" style="height:3.05em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">i</span></span></span><span style="top:-3.05em;"><span class="pstrut" style="height:3.05em;"></span><span><span class="mop op-symbol large-op">∑</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:1.2777em;"><span></span></span></span></span></span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mopen nulldelimiter"></span><span class="mfrac"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:1.4911em;"><span style="top:-2.314em;"><span class="pstrut" style="height:3em;"></span><span class="mord"><span class="mord mathnormal">a</span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0359em;">y</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3117em;"><span style="top:-2.55em;margin-left:-0.0359em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">i</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">+</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mord mathnormal">b</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">+</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mord mathnormal">ε</span></span></span><span style="top:-3.23em;"><span class="pstrut" style="height:3em;"></span><span class="frac-line" style="border-bottom-width:0.04em;"></span></span><span style="top:-3.677em;"><span class="pstrut" style="height:3em;"></span><span class="mord"><span class="mopen">(</span><span class="mord"><span class="mord mathnormal">x</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3117em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">i</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">−</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0359em;">y</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3117em;"><span style="top:-2.55em;margin-left:-0.0359em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">i</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mclose"><span class="mclose">)</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.8141em;"><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">2</span></span></span></span></span></span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.8804em;"><span></span></span></span></span></span><span class="mclose nulldelimiter"></span></span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">+</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:2.3277em;vertical-align:-1.2777em;"></span><span class="mord mathnormal">λ</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mop op-limits"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:1.05em;"><span style="top:-1.8723em;margin-left:0em;"><span class="pstrut" style="height:3.05em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">i</span></span></span><span style="top:-3.05em;"><span class="pstrut" style="height:3.05em;"></span><span><span class="mop op-symbol large-op">∑</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:1.2777em;"><span></span></span></span></span></span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord mathnormal">ρ</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight" style="margin-right:0.0379em;">δ</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mopen">(</span><span class="mord">∣∇</span><span class="mord"><span class="mord mathnormal">x</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3117em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">i</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mord">∣</span><span class="mclose">)</span></span></span></span></span></p><p>整个目标函数由两部分组成。</p><h3 id="noise-aware-fidelity" tabindex="-1"><a class="header-anchor" href="#noise-aware-fidelity"><span>Noise-Aware Fidelity</span></a></h3><p class="katex-block"><span class="katex-display"><span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML" display="block"><semantics><mrow><mfrac><mrow><mo stretchy="false">(</mo><msub><mi>x</mi><mi>i</mi></msub><mo>−</mo><msub><mi>y</mi><mi>i</mi></msub><msup><mo stretchy="false">)</mo><mn>2</mn></msup></mrow><mrow><mi>a</mi><msub><mi>y</mi><mi>i</mi></msub><mo>+</mo><mi>b</mi><mo>+</mo><mi>ε</mi></mrow></mfrac></mrow><annotation encoding="application/x-tex">\\frac{(x_i-y_i)^2} {ay_i+b+\\varepsilon} </annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:2.3715em;vertical-align:-0.8804em;"></span><span class="mord"><span class="mopen nulldelimiter"></span><span class="mfrac"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:1.4911em;"><span style="top:-2.314em;"><span class="pstrut" style="height:3em;"></span><span class="mord"><span class="mord mathnormal">a</span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0359em;">y</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3117em;"><span style="top:-2.55em;margin-left:-0.0359em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">i</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">+</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mord mathnormal">b</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">+</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mord mathnormal">ε</span></span></span><span style="top:-3.23em;"><span class="pstrut" style="height:3em;"></span><span class="frac-line" style="border-bottom-width:0.04em;"></span></span><span style="top:-3.677em;"><span class="pstrut" style="height:3em;"></span><span class="mord"><span class="mopen">(</span><span class="mord"><span class="mord mathnormal">x</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3117em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">i</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">−</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0359em;">y</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3117em;"><span style="top:-2.55em;margin-left:-0.0359em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">i</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mclose"><span class="mclose">)</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.8141em;"><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">2</span></span></span></span></span></span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.8804em;"><span></span></span></span></span></span><span class="mclose nulldelimiter"></span></span></span></span></span></span></p><p>传统 L2 Fidelity 默认所有像素具有相同噪声水平。</p><p>这里则根据当前像素估计的 Noise Variance 自适应调整权重。</p><p>噪声越大的区域，对观测 RAW 的信任程度越低；噪声较小的区域，则更多保留原始 Sensor 信息。</p><hr><h3 id="huber-tv-regularization" tabindex="-1"><a class="header-anchor" href="#huber-tv-regularization"><span>Huber-TV Regularization</span></a></h3><p>空间约束采用：</p><p class="katex-block"><span class="katex-display"><span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML" display="block"><semantics><mrow><mi>λ</mi><munder><mo>∑</mo><mi>i</mi></munder><msub><mi>ρ</mi><mi>δ</mi></msub><mo stretchy="false">(</mo><mi mathvariant="normal">∣</mi><mi mathvariant="normal">∇</mi><msub><mi>x</mi><mi>i</mi></msub><mi mathvariant="normal">∣</mi><mo stretchy="false">)</mo></mrow><annotation encoding="application/x-tex">\\lambda\\sum_i\\rho_\\delta(|\\nabla x_i|) </annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:2.3277em;vertical-align:-1.2777em;"></span><span class="mord mathnormal">λ</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mop op-limits"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:1.05em;"><span style="top:-1.8723em;margin-left:0em;"><span class="pstrut" style="height:3.05em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">i</span></span></span><span style="top:-3.05em;"><span class="pstrut" style="height:3.05em;"></span><span><span class="mop op-symbol large-op">∑</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:1.2777em;"><span></span></span></span></span></span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord mathnormal">ρ</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight" style="margin-right:0.0379em;">δ</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mopen">(</span><span class="mord">∣∇</span><span class="mord"><span class="mord mathnormal">x</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3117em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">i</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mord">∣</span><span class="mclose">)</span></span></span></span></span></p><p>TV Regularization 可以抑制随机噪声，但纯 TV 容易造成 Staircase Artifact。</p><p>因此引入 Huber Loss，使小梯度区域保持平滑，同时减少对真实强边缘的过度惩罚。</p><p>最终希望实现三者之间的平衡：</p><div class="language-text line-numbers-mode" data-highlighter="shiki" data-ext="text" style="--shiki-light:#383A42;--shiki-dark:#abb2bf;--shiki-light-bg:#FAFAFA;--shiki-dark-bg:#282c34;"><pre class="shiki shiki-themes one-light one-dark-pro vp-code"><code class="language-text"><span class="line"><span>Noise Suppression</span></span>
<span class="line"><span>        +</span></span>
<span class="line"><span>Edge Preservation</span></span>
<span class="line"><span>        +</span></span>
<span class="line"><span>Local Structure Preservation</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><hr><h1 id="六、基于-sidd-的真实手机噪声实验" tabindex="-1"><a class="header-anchor" href="#六、基于-sidd-的真实手机噪声实验"><span>六、基于 SIDD 的真实手机噪声实验</span></a></h1><p>为了避免算法只在人工 Gaussian Noise 上有效，项目进一步使用 SIDD 真实手机噪声数据进行验证。</p><p>实验数据包含：</p><div class="language-text line-numbers-mode" data-highlighter="shiki" data-ext="text" style="--shiki-light:#383A42;--shiki-dark:#abb2bf;--shiki-light-bg:#FAFAFA;--shiki-dark-bg:#282c34;"><pre class="shiki shiki-themes one-light one-dark-pro vp-code"><code class="language-text"><span class="line"><span>Noisy RAW</span></span>
<span class="line"><span>Ground Truth RAW</span></span>
<span class="line"><span>Metadata</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>恢复过程直接作用于 Bayer RAW，而不是先转换到 JPEG 后再进行去噪。</p><p>处理完成后统一生成：</p><div class="language-text line-numbers-mode" data-highlighter="shiki" data-ext="text" style="--shiki-light:#383A42;--shiki-dark:#abb2bf;--shiki-light-bg:#FAFAFA;--shiki-dark-bg:#282c34;"><pre class="shiki shiki-themes one-light one-dark-pro vp-code"><code class="language-text"><span class="line"><span>Noisy</span></span>
<span class="line"><span>Denoised</span></span>
<span class="line"><span>Ground Truth</span></span>
<span class="line"><span>Compare View</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>并计算：</p><div class="language-text line-numbers-mode" data-highlighter="shiki" data-ext="text" style="--shiki-light:#383A42;--shiki-dark:#abb2bf;--shiki-light-bg:#FAFAFA;--shiki-dark-bg:#282c34;"><pre class="shiki shiki-themes one-light one-dark-pro vp-code"><code class="language-text"><span class="line"><span>PSNR Before</span></span>
<span class="line"><span>PSNR After</span></span>
<span class="line"><span>PSNR Improvement</span></span>
<span class="line"><span>SSIM</span></span>
<span class="line"><span>Runtime</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>因此算法效果可以同时从两个维度评价：</p><div class="language-text line-numbers-mode" data-highlighter="shiki" data-ext="text" style="--shiki-light:#383A42;--shiki-dark:#abb2bf;--shiki-light-bg:#FAFAFA;--shiki-dark-bg:#282c34;"><pre class="shiki shiki-themes one-light one-dark-pro vp-code"><code class="language-text"><span class="line"><span>Subjective Image Quality</span></span>
<span class="line"><span>        +</span></span>
<span class="line"><span>Objective IQ Metrics</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>当前展示平台已经支持 SIDD 内置样例运行，并展示 Noisy、Denoised、GT 及 PSNR / SSIM 等结果。</p><hr><h1 id="七、统一到标准-bayer-raw" tabindex="-1"><a class="header-anchor" href="#七、统一到标准-bayer-raw"><span>七、统一到标准 Bayer RAW</span></a></h1><p>Quad-Bayer Remosaic 和 RAW Denoise 本质上并不是两个孤立算法。</p><p>前者解决：</p><blockquote><p>Sensor CFA 结构发生变化以后，如何重新得到标准 Bayer Sampling。</p></blockquote><p>后者解决：</p><blockquote><p>Bayer RAW 中存在真实 Sensor Noise 时，如何恢复更加可靠的像素值。</p></blockquote><p>因此 OpenCameraIQ 将两条路径统一到 Standard Bayer RAW：</p><div class="language-text line-numbers-mode" data-highlighter="shiki" data-ext="text" style="--shiki-light:#383A42;--shiki-dark:#abb2bf;--shiki-light-bg:#FAFAFA;--shiki-dark-bg:#282c34;"><pre class="shiki shiki-themes one-light one-dark-pro vp-code"><code class="language-text"><span class="line"><span>                    RAW Input</span></span>
<span class="line"><span>                        ↓</span></span>
<span class="line"><span>                 Camera Metadata</span></span>
<span class="line"><span>                        ↓</span></span>
<span class="line"><span>                       BLC</span></span>
<span class="line"><span>                        ↓</span></span>
<span class="line"><span>          ┌─────────────┴─────────────┐</span></span>
<span class="line"><span>          │                           │</span></span>
<span class="line"><span>          │                           │</span></span>
<span class="line"><span>   Quad-Bayer RAW                Noisy Bayer RAW</span></span>
<span class="line"><span>          │                           │</span></span>
<span class="line"><span>          ↓                           ↓</span></span>
<span class="line"><span>  CFA Pattern Analysis         Noise Estimation</span></span>
<span class="line"><span>          │                           │</span></span>
<span class="line"><span>          ↓                           ↓</span></span>
<span class="line"><span> Pattern-Aware                Noise-Aware</span></span>
<span class="line"><span>    Remosaic                   Restoration</span></span>
<span class="line"><span>          │                           │</span></span>
<span class="line"><span>          └─────────────┬─────────────┘</span></span>
<span class="line"><span>                        ↓</span></span>
<span class="line"><span>                Standard Bayer RAW</span></span>
<span class="line"><span>                        ↓</span></span>
<span class="line"><span>                    Demosaic</span></span>
<span class="line"><span>                        ↓</span></span>
<span class="line"><span>                  AWB + CCM</span></span>
<span class="line"><span>                        ↓</span></span>
<span class="line"><span>                Gamma / Tone</span></span>
<span class="line"><span>                        ↓</span></span>
<span class="line"><span>                 IQ Evaluation</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>这个设计的重点在于：</p><blockquote><p>图像恢复不是独立于 Camera Pipeline 存在，而是 ISP Pipeline 中的一个 Processing Block。</p></blockquote><hr><h1 id="八、raw-pipeline-中的-blc" tabindex="-1"><a class="header-anchor" href="#八、raw-pipeline-中的-blc"><span>八、RAW Pipeline 中的 BLC</span></a></h1><p>在 RAW Pipeline 中，Black Level Correction 通常是非常靠前的一步。</p><p>Sensor 即使没有实际光输入，也可能输出一个非零 Digital Value。</p><p>因此需要进行：</p><p class="katex-block"><span class="katex-display"><span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML" display="block"><semantics><mrow><msub><mi>I</mi><mtext>corrected</mtext></msub><mo>=</mo><mo>=</mo><mo>=</mo><mo>=</mo><mo>=</mo><mo>=</mo><mo>=</mo><mo>=</mo><mo>=</mo><mo>=</mo><mo>=</mo><mo>=</mo><mo>=</mo><mo>=</mo><mo>=</mo><mo>=</mo><mo>=</mo><mo>=</mo><mo>=</mo><mo>=</mo><mi mathvariant="normal">clamp</mi><mo>⁡</mo><mo stretchy="false">(</mo><msub><mi>I</mi><mtext>raw</mtext></msub><mo>−</mo><mi>B</mi><mo separator="true">,</mo><mn>0</mn><mo separator="true">,</mo><mi>W</mi><mo>−</mo><mi>B</mi><mo stretchy="false">)</mo></mrow><annotation encoding="application/x-tex">I_{\\text{corrected}} ==================== \\operatorname{clamp} (I_{\\text{raw}}-B,0,W-B) </annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8333em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0785em;">I</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:-0.0785em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord text mtight"><span class="mord mtight">corrected</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">====================</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mop"><span class="mord mathrm">clamp</span></span><span class="mopen">(</span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0785em;">I</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.1514em;"><span style="top:-2.55em;margin-left:-0.0785em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord text mtight"><span class="mord mtight">raw</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">−</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.8778em;vertical-align:-0.1944em;"></span><span class="mord mathnormal" style="margin-right:0.0502em;">B</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord">0</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal" style="margin-right:0.1389em;">W</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">−</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord mathnormal" style="margin-right:0.0502em;">B</span><span class="mclose">)</span></span></span></span></span></p><p>随后归一化：</p><p class="katex-block"><span class="katex-display"><span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML" display="block"><semantics><mrow><msub><mi>I</mi><mtext>norm</mtext></msub><mo>=</mo><mo>=</mo><mo>=</mo><mo>=</mo><mo>=</mo><mo>=</mo><mo>=</mo><mo>=</mo><mo>=</mo><mo>=</mo><mo>=</mo><mo>=</mo><mo>=</mo><mo>=</mo><mo>=</mo><mfrac><msub><mi>I</mi><mtext>corrected</mtext></msub><mrow><mi>W</mi><mo>−</mo><mi>B</mi></mrow></mfrac></mrow><annotation encoding="application/x-tex">I_{\\text{norm}} =============== \\frac{I_{\\text{corrected}}} {W-B} </annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8333em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0785em;">I</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.1514em;"><span style="top:-2.55em;margin-left:-0.0785em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord text mtight"><span class="mord mtight">norm</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">===============</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:2.1297em;vertical-align:-0.7693em;"></span><span class="mord"><span class="mopen nulldelimiter"></span><span class="mfrac"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:1.3603em;"><span style="top:-2.314em;"><span class="pstrut" style="height:3em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.1389em;">W</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">−</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mord mathnormal" style="margin-right:0.0502em;">B</span></span></span><span style="top:-3.23em;"><span class="pstrut" style="height:3em;"></span><span class="frac-line" style="border-bottom-width:0.04em;"></span></span><span style="top:-3.677em;"><span class="pstrut" style="height:3em;"></span><span class="mord"><span class="mord"><span class="mord mathnormal" style="margin-right:0.0785em;">I</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:-0.0785em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord text mtight"><span class="mord mtight">corrected</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.7693em;"><span></span></span></span></span></span><span class="mclose nulldelimiter"></span></span></span></span></span></span></p><p>其中：</p><ul><li>(B)：Black Level；</li><li>(W)：White Level。</li></ul><p>如果没有正确执行 BLC，后续很多模块都会受到影响，包括：</p><div class="language-text line-numbers-mode" data-highlighter="shiki" data-ext="text" style="--shiki-light:#383A42;--shiki-dark:#abb2bf;--shiki-light-bg:#FAFAFA;--shiki-dark-bg:#282c34;"><pre class="shiki shiki-themes one-light one-dark-pro vp-code"><code class="language-text"><span class="line"><span>Demosaic</span></span>
<span class="line"><span>Noise Estimation</span></span>
<span class="line"><span>AWB</span></span>
<span class="line"><span>CCM</span></span>
<span class="line"><span>Tone Mapping</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>因此 OpenCameraIQ 的目标并不是直接在输入图像上调用一个算法，而是按照真实 Camera ISP 的顺序组织数据。</p><p>项目整体规划的 ISP 顺序为：</p><div class="language-text line-numbers-mode" data-highlighter="shiki" data-ext="text" style="--shiki-light:#383A42;--shiki-dark:#abb2bf;--shiki-light-bg:#FAFAFA;--shiki-dark-bg:#282c34;"><pre class="shiki shiki-themes one-light one-dark-pro vp-code"><code class="language-text"><span class="line"><span>RAW</span></span>
<span class="line"><span> ↓</span></span>
<span class="line"><span>BLC</span></span>
<span class="line"><span> ↓</span></span>
<span class="line"><span>Demosaic</span></span>
<span class="line"><span> ↓</span></span>
<span class="line"><span>AWB Gain</span></span>
<span class="line"><span> ↓</span></span>
<span class="line"><span>CCM</span></span>
<span class="line"><span> ↓</span></span>
<span class="line"><span>Gamma</span></span>
<span class="line"><span> ↓</span></span>
<span class="line"><span>Denoise</span></span>
<span class="line"><span> ↓</span></span>
<span class="line"><span>Sharpen</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>这种模块化 ISP 路线也是项目后续继续扩展的核心。</p><hr><h1 id="九、c-isp-工程架构" tabindex="-1"><a class="header-anchor" href="#九、c-isp-工程架构"><span>九、C++ ISP 工程架构</span></a></h1><p>除了图像算法本身，我还希望把算法放进一个接近实际 Camera 工程的数据流中进行验证。</p><p>因此项目在 C++ 侧定义了统一的数据结构和 Pipeline Interface。</p><p>整体数据流：</p><div class="language-text line-numbers-mode" data-highlighter="shiki" data-ext="text" style="--shiki-light:#383A42;--shiki-dark:#abb2bf;--shiki-light-bg:#FAFAFA;--shiki-dark-bg:#282c34;"><pre class="shiki shiki-themes one-light one-dark-pro vp-code"><code class="language-text"><span class="line"><span>Camera Source</span></span>
<span class="line"><span>      ↓</span></span>
<span class="line"><span>    Frame</span></span>
<span class="line"><span>      ↓</span></span>
<span class="line"><span>ISP Pipeline</span></span>
<span class="line"><span>      ↓</span></span>
<span class="line"><span>Frame Metrics</span></span>
<span class="line"><span>      ↓</span></span>
<span class="line"><span>Web Tuning Console</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>其中 Camera Source 与上层 ISP 解耦。</p><p>当前使用 <code>MockCamera</code> 完成工程链路验证，后续可以替换为：</p><div class="language-text line-numbers-mode" data-highlighter="shiki" data-ext="text" style="--shiki-light:#383A42;--shiki-dark:#abb2bf;--shiki-light-bg:#FAFAFA;--shiki-dark-bg:#282c34;"><pre class="shiki shiki-themes one-light one-dark-pro vp-code"><code class="language-text"><span class="line"><span>DngCamera</span></span>
<span class="line"><span>UsbCamera</span></span>
<span class="line"><span>LibcameraCamera</span></span>
<span class="line"><span>AndroidCamera</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>而上层 Frame、ISP Pipeline、Metrics 和调试 UI 不需要整体重写。</p><p>这也是项目在工程设计上比较核心的一点：</p><blockquote><p>Camera 输入可以替换，但上层数据接口保持稳定。</p></blockquote><p>项目当前已经完成 CMake + C++ Backend、MockCamera、Frame、CameraMetadata、IspPipeline、HTTP/WebSocket 与基础测试。</p><hr><h1 id="十、web-tuning-console" tabindex="-1"><a class="header-anchor" href="#十、web-tuning-console"><span>十、Web Tuning Console</span></a></h1><p>为了避免图像算法变成“输入一张图，输出一张图”的黑盒实验，OpenCameraIQ 同时搭建了 Web Tuning Console。</p><p>目前可以观察：</p><div class="language-text line-numbers-mode" data-highlighter="shiki" data-ext="text" style="--shiki-light:#383A42;--shiki-dark:#abb2bf;--shiki-light-bg:#FAFAFA;--shiki-dark-bg:#282c34;"><pre class="shiki shiki-themes one-light one-dark-pro vp-code"><code class="language-text"><span class="line"><span>Image Preview</span></span>
<span class="line"><span>Histogram</span></span>
<span class="line"><span>Exposure / ISO</span></span>
<span class="line"><span>AWB Gain</span></span>
<span class="line"><span>Luma</span></span>
<span class="line"><span>ISP Latency</span></span>
<span class="line"><span>FPS</span></span>
<span class="line"><span>CPU Usage</span></span>
<span class="line"><span>Image Quality Metrics</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>其作用不是做一个完整 Camera App，而是作为 ISP Algorithm Debugging Interface。</p><p>典型闭环是：</p><div class="language-text line-numbers-mode" data-highlighter="shiki" data-ext="text" style="--shiki-light:#383A42;--shiki-dark:#abb2bf;--shiki-light-bg:#FAFAFA;--shiki-dark-bg:#282c34;"><pre class="shiki shiki-themes one-light one-dark-pro vp-code"><code class="language-text"><span class="line"><span>调整参数</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>运行 ISP / Restoration</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>观察输出图像</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>查看 Histogram / Metrics</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>比较 IQ</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>继续调整</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>这样每一个 ISP Block 都可以进一步分析：</p><ul><li>输入是什么；</li><li>输出是什么；</li><li>参数是什么；</li><li>对画质有什么影响；</li><li>Runtime 是多少；</li><li>Failure Case 是什么。</li></ul><p>项目本身也是按照“输入数据 → 算法处理 → 统计指标 → 可视化 → 参数调整 → 测试验证”的闭环进行组织。</p><hr><h1 id="十一、当前阶段与后续方向" tabindex="-1"><a class="header-anchor" href="#十一、当前阶段与后续方向"><span>十一、当前阶段与后续方向</span></a></h1><p>当前 OpenCameraIQ 已经完成了第一阶段工程框架，并将 Quad-Bayer 和真实 RAW Noise Restoration 实验接入展示平台。</p><p>目前工程主链已经能够完成：</p><div class="language-text line-numbers-mode" data-highlighter="shiki" data-ext="text" style="--shiki-light:#383A42;--shiki-dark:#abb2bf;--shiki-light-bg:#FAFAFA;--shiki-dark-bg:#282c34;"><pre class="shiki shiki-themes one-light one-dark-pro vp-code"><code class="language-text"><span class="line"><span>C++ Camera / ISP Framework</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>RAW Restoration Experiment</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>Metrics</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>Web Visualization</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>需要说明的是，当前 Quad-Bayer 与 SIDD 恢复模块仍属于独立算法实验模块，而 C++ 侧重点是 Camera、Frame、ISP Pipeline、Metrics 以及前后端通信框架。</p><p>也就是说，当前项目更强调：</p><blockquote><p>先把算法、数据接口、评价指标和工程链路验证清楚，再逐步将成熟算法沉淀为标准 ISP Block。</p></blockquote><p>当前 C++ 主链实际接入的是 <code>MockCamera → IspPipeline</code>，Quad-Bayer 和 SIDD 算法则复用已经验证过的独立实验流程，因此不会把尚未迁移到 C++ 的算法包装成已经完成的 C++ ISP 实现。</p><p>后续主要继续完成：</p><div class="language-text line-numbers-mode" data-highlighter="shiki" data-ext="text" style="--shiki-light:#383A42;--shiki-dark:#abb2bf;--shiki-light-bg:#FAFAFA;--shiki-dark-bg:#282c34;"><pre class="shiki shiki-themes one-light one-dark-pro vp-code"><code class="language-text"><span class="line"><span>RawFrame</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>Real BLC</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>Demosaic</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>AWB Gain</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>CCM</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>Gamma</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>RAW Denoise</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>Sharpen</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>并进一步加入：</p><div class="language-text line-numbers-mode" data-highlighter="shiki" data-ext="text" style="--shiki-light:#383A42;--shiki-dark:#abb2bf;--shiki-light-bg:#FAFAFA;--shiki-dark-bg:#282c34;"><pre class="shiki shiki-themes one-light one-dark-pro vp-code"><code class="language-text"><span class="line"><span>AE</span></span>
<span class="line"><span>AWB</span></span>
<span class="line"><span>AF</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>构成完整的 Camera IQ 实验平台。</p><hr><h1 id="总结" tabindex="-1"><a class="header-anchor" href="#总结"><span>总结</span></a></h1><p>OpenCameraIQ 最开始来源于两个 RAW 图像问题：</p><p>一个是：</p><blockquote><p><strong>Quad-Bayer 特殊采样结构应该如何恢复？</strong></p></blockquote><p>另一个是：</p><blockquote><p><strong>真实 Sensor Noise 应该如何建模和去除？</strong></p></blockquote><p>但随着实验继续推进，我发现单独讨论算法并不足以理解 Camera 图像处理。</p><p>真正完整的问题应该是：</p><div class="language-text line-numbers-mode" data-highlighter="shiki" data-ext="text" style="--shiki-light:#383A42;--shiki-dark:#abb2bf;--shiki-light-bg:#FAFAFA;--shiki-dark-bg:#282c34;"><pre class="shiki shiki-themes one-light one-dark-pro vp-code"><code class="language-text"><span class="line"><span>Sensor 如何采样</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>RAW 如何表示</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>Metadata 如何影响处理</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>ISP 如何组织算法</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>图像质量如何评价</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>算法如何调试和验证</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>因此最终将项目扩展为 OpenCameraIQ。</p><p>它并不是追求实现一个完整商业 Camera ISP，而是希望用一个规模可控的工程，把 <strong>RAW、ISP、图像恢复、Camera 数据流、IQ Metrics 和调试工具</strong>真正串起来。</p><p>相比单独实现某一个算法，这个项目更关注的是：</p><blockquote><p><strong>一个图像算法，如何从数学模型变成 Camera Pipeline 中可以解释、可以测试、可以评价、可以调试的工程模块。</strong></p></blockquote>`,169)]])}var s=r(a,[[`render`,o]]);export{i as _pageData,s as default};